import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e}from"./app-4490560f.js";const t={},o=e(`<h1 id="htop-交互式进程查看器-top-的增强版" tabindex="-1"><a class="header-anchor" href="#htop-交互式进程查看器-top-的增强版" aria-hidden="true">#</a> htop（交互式进程查看器，top 的增强版）</h1><blockquote><p>Homebrew 版本 3.4.1 ｜ 主页：见官方文档 ｜ 安装：<code>brew install htop</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>htop 是一个<strong>交互式进程查看器</strong>，是经典 <code>top</code> 命令的增强替代品。它以彩色、可视化的方式实时展示 CPU、内存、交换分区的使用情况，并将所有进程按树形层级展示，支持用鼠标或键盘直接操作，无需记忆繁琐的命令行参数。</p><p>相比 <code>top</code>，htop 最大的价值在于<strong>可交互</strong>：可以横着/竖着滚动查看长列表、直接按 F 键或用鼠标选中进程进行 kill（杀死）、renice（调整优先级）、搜索进程等，并且启动即可用、无需任何配置。典型应用场景：排查 CPU 或内存被谁吃满、定位僵尸进程、快速结束卡死的进程、观察系统整体负载趋势。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装、升级、卸载，以及验证：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> <span class="token function">htop</span>

<span class="token comment"># 升级到最新版</span>
brew upgrade <span class="token function">htop</span>

<span class="token comment"># 卸载</span>
brew uninstall <span class="token function">htop</span>

<span class="token comment"># 验证安装成功（应输出 htop 3.4.1 之类）</span>
<span class="token function">htop</span> <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果命令提示找不到，可先用 <code>brew update</code> 更新索引再安装；某些 macOS 老版本还需先安装 Xcode Command Line Tools。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>htop 分为「启动参数」和「运行中快捷键」两类，运行中的快捷键可以直接按字母键触发（不区分大小写，多个同键可在菜单里循环切换）：</p><table><thead><tr><th>命令 / 按键</th><th>参数说明</th><th>示例 / 说明</th></tr></thead><tbody><tr><td><code>htop</code></td><td>直接启动，默认展示全部进程</td><td><code>htop</code></td></tr><tr><td><code>htop -p PID</code></td><td>只显示指定 PID 的进程</td><td><code>htop -p 1234,5678</code>（PID 用逗号分隔）</td></tr><tr><td><code>htop -u 用户名</code></td><td>只显示某用户的进程</td><td><code>htop -u wangbo</code></td></tr><tr><td><code>htop -d N</code></td><td>刷新间隔设为 N 秒（默认 1 秒）</td><td><code>htop -d 3</code>（每 3 秒刷新）</td></tr><tr><td><code>htop -t</code></td><td>启动即以树形视图显示</td><td><code>htop -t</code></td></tr><tr><td><code>F3</code>（<code>/</code>）</td><td>搜索进程名</td><td>输入关键字即可定位进程</td></tr><tr><td><code>F4</code>（<code>\\</code>）</td><td>按关键字过滤进程</td><td>配合 <code>\\</code> 再次输入清除过滤</td></tr><tr><td><code>F5</code>（<code>t</code>）</td><td>切换树形 / 列表视图</td><td>按 <code>t</code> 同样可切换</td></tr><tr><td><code>F6</code>（<code>&gt;</code>）</td><td>选择进程排序字段</td><td>如按内存 <code>MEM%</code> 或 CPU 排序</td></tr><tr><td><code>F9</code>（<code>k</code>）</td><td>杀死选中进程</td><td>会弹出信号列表，选 <code>SIGKILL</code>/<code>SIGTERM</code></td></tr><tr><td><code>F7</code> / <code>F8</code></td><td>提高 / 降低选中进程优先级（renice）</td><td>只对有权操作的进程生效</td></tr><tr><td><code>F10</code>（<code>q</code>）</td><td>退出 htop</td><td>直接按 <code>q</code> 更快</td></tr><tr><td><code>空格</code></td><td>标记（tag）进程，便于批量操作</td><td>可配合 F9 一次杀掉多个进程</td></tr><tr><td><code>F1</code>（<code>?</code>）</td><td>打开帮助页</td><td>里面列出全部快捷键</td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-启动-htop-并筛选出-cpu-占用最高的进程" tabindex="-1"><a class="header-anchor" href="#示例-1-启动-htop-并筛选出-cpu-占用最高的进程" aria-hidden="true">#</a> 示例 1：启动 htop 并筛选出 CPU 占用最高的进程</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 直接启动</span>
<span class="token function">htop</span>

<span class="token comment"># 2. 在运行界面中，按 F6（或 &gt;）弹出排序字段选择，</span>
<span class="token comment">#    用方向键选中 PERCENT_CPU，回车确认，进程即按 CPU 使用率降序排列</span>
<span class="token comment"># 3. 若只想看占用高的几个，按 F4 输入关键字过滤，或直接观察顶部彩色进度条</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：顶部彩色进度条实时反映各 CPU 核心（含逻辑核心）的使用率，列表第一行就是当前最吃 CPU 的进程。</p><h3 id="示例-2-按用户名监控并树形查看进程" tabindex="-1"><a class="header-anchor" href="#示例-2-按用户名监控并树形查看进程" aria-hidden="true">#</a> 示例 2：按用户名监控并树形查看进程</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只查看用户 wangbo 的进程，并以树形视图展示父子关系</span>
<span class="token function">htop</span> <span class="token parameter variable">-u</span> wangbo <span class="token parameter variable">-t</span>

<span class="token comment"># 运行中按 F5 可随时在&quot;树形 / 列表&quot;两种视图间来回切换</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：能看到每个进程及其父进程的层级关系，便于判断哪些进程是谁拉起的。</p><h3 id="示例-3-定位并杀死一个卡死的进程" tabindex="-1"><a class="header-anchor" href="#示例-3-定位并杀死一个卡死的进程" aria-hidden="true">#</a> 示例 3：定位并杀死一个卡死的进程</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 启动 htop 并按 F5 切到树形视图</span>
<span class="token function">htop</span>

<span class="token comment"># 2. 按 / 搜索进程名，例如卡死的 node 服务</span>
<span class="token comment">#    输入 node 回车后光标自动跳到对应进程</span>

<span class="token comment"># 3. 按 F9 弹出信号列表，用方向键选中 SIGKILL，回车确认</span>
<span class="token comment">#    （或用 F4 过滤出该进程，再空格标记、F9 批量处理）</span>

<span class="token comment"># 4. 观察列表，该进程已消失，说明已成功终止</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-调整刷新间隔-并在排查端口占用时聚焦观察" tabindex="-1"><a class="header-anchor" href="#示例-4-调整刷新间隔-并在排查端口占用时聚焦观察" aria-hidden="true">#</a> 示例 4：调整刷新间隔，并在排查端口占用时聚焦观察</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 每 3 秒刷新一次，避免默认 1 秒刷新占用太多 CPU</span>
<span class="token function">htop</span> <span class="token parameter variable">-d</span> <span class="token number">3</span>

<span class="token comment"># 排查端口占用时，先找到占用 8080 的进程 PID，再进入 htop 精确观察其资源占用</span>
<span class="token function">lsof</span> <span class="token parameter variable">-nP</span> <span class="token parameter variable">-iTCP:8080</span> <span class="token parameter variable">-sTCP:LISTEN</span>   <span class="token comment"># 输出中的 PID 列即为占用进程</span>
<span class="token function">htop</span> <span class="token parameter variable">-p</span> <span class="token number">8080</span>                      <span class="token comment"># 改用上面查到的 PID，例如：htop -p 12345</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>htop -p</code> 后面要填<strong>进程 PID</strong>，不是端口号。想查端口 8080 被谁占用，请先用 <code>lsof -nP -iTCP:8080 -sTCP:LISTEN</code> 拿到 PID，再 <code>htop -p &lt;PID&gt;</code> 聚焦观察该进程的 CPU/内存。</p></blockquote><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-配置文件位置与结构" tabindex="-1"><a class="header-anchor" href="#_1-配置文件位置与结构" aria-hidden="true">#</a> 1. 配置文件位置与结构</h3><p>htop 的配置保存在 <code>~/.config/htop/htoprc</code>（新版 3.x）或 <code>~/.htoprc</code>（旧版 2.x）。首次退出时自动生成。配置文件是<strong>键值对</strong>格式，可直接手写。常用配置项如下：</p><div class="language-ini line-numbers-mode" data-ext="ini"><pre class="language-ini"><code><span class="token comment"># ~/.config/htop/htoprc</span>
<span class="token comment"># 布局相关</span>
<span class="token key attr-name">left_meters</span><span class="token punctuation">=</span><span class="token value attr-value">AllCPUs Memory Swap        # 左侧 Meters 显示哪些指标</span>
<span class="token key attr-name">right_meters</span><span class="token punctuation">=</span><span class="token value attr-value">Tasks LoadAverage Uptime  # 右侧 Meters 显示哪些指标</span>
<span class="token key attr-name">left_meter_modes</span><span class="token punctuation">=</span><span class="token value attr-value">1 1 1                 # 1=条形图 2=数字 3=文字，数量需与 left_meters 对应</span>
<span class="token key attr-name">right_meter_modes</span><span class="token punctuation">=</span><span class="token value attr-value">2 2 2</span>

<span class="token comment"># 显示相关</span>
<span class="token key attr-name">show_cpu_frequency</span><span class="token punctuation">=</span><span class="token value attr-value">1                   # 显示 CPU 频率</span>
<span class="token key attr-name">show_cpu_temperature</span><span class="token punctuation">=</span><span class="token value attr-value">1                 # 显示 CPU 温度（需对应传感器，mac 上可能无效）</span>
<span class="token key attr-name">show_program_path</span><span class="token punctuation">=</span><span class="token value attr-value">0                    # 是否显示完整程序路径</span>
<span class="token key attr-name">highlight_base_name</span><span class="token punctuation">=</span><span class="token value attr-value">1                  # 高亮进程名而非完整命令</span>
<span class="token key attr-name">highlight_deleted_exe</span><span class="token punctuation">=</span><span class="token value attr-value">1                # 高亮已被删除的可执行文件（磁盘上的 bin 被删）</span>
<span class="token key attr-name">hide_kernel_threads</span><span class="token punctuation">=</span><span class="token value attr-value">uwmY5PYwRXtihc9O   # 是否隐藏内核线程（0 显示 / 1 隐藏）</span>
<span class="token key attr-name">hide_userland_threads</span><span class="token punctuation">=</span><span class="token value attr-value">0                # 是否隐藏用户态线程</span>

<span class="token comment"># 树形视图</span>
<span class="token key attr-name">tree_view</span><span class="token punctuation">=</span><span class="token value attr-value">0                            # 1 默认树形视图，0 默认列表</span>
<span class="token key attr-name">sort_key</span><span class="token punctuation">=</span><span class="token value attr-value">PERCENT_MEM                    # 默认排序字段（见下方常见排序键）</span>
<span class="token key attr-name">sort_direction</span><span class="token punctuation">=</span><span class="token value attr-value">1                       # 1 降序 0 升序</span>

<span class="token comment"># 颜色主题</span>
<span class="token key attr-name">color_scheme</span><span class="token punctuation">=</span><span class="token value attr-value">0                         # 0 默认 1 Monochrome 2 Black on White</span>
<span class="token key attr-name">enable_mouse</span><span class="token punctuation">=</span><span class="token value attr-value">1                         # 是否启用鼠标支持</span>
<span class="token key attr-name">delay</span><span class="token punctuation">=</span><span class="token value attr-value">15                               # 刷新间隔（1/10 秒单位，15 = 1.5 秒）</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>常见排序键（<code>sort_key</code> 可选值）</strong>：<code>PID</code>、<code>USER</code>、<code>PERCENT_CPU</code>、<code>PERCENT_MEM</code>、<code>M_RESIDENT</code>、<code>M_SIZE</code>、<code>TIME</code>、<code>COMMAND</code>。改这个键等价于在界面里按 <code>F6</code> 选排序字段。</p><h3 id="_2-常用环境变量与启动参数" tabindex="-1"><a class="header-anchor" href="#_2-常用环境变量与启动参数" aria-hidden="true">#</a> 2. 常用环境变量与启动参数</h3><p>htop 除 <code>-d/-u/-p/-t</code> 外，还有一批实用启动参数，适合放进别名或脚本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">htop</span> <span class="token parameter variable">-h</span>                     <span class="token comment"># 查看完整帮助</span>
<span class="token function">htop</span> <span class="token parameter variable">-C</span>                     <span class="token comment"># 纯色（Monochrome）模式，适合浅色背景终端</span>
<span class="token function">htop</span> <span class="token parameter variable">-s</span> PERCENT_MEM        <span class="token comment"># 启动即按内存排序</span>
<span class="token function">htop</span> <span class="token parameter variable">-F</span>                     <span class="token comment"># 只显示指定 PID 及其子进程：htop -F 1234</span>
<span class="token function">htop</span> <span class="token parameter variable">--tree</span>                 <span class="token comment"># 等价于 -t，启动即以树形视图显示</span>
<span class="token function">htop</span> --no-color             <span class="token comment"># 等价于 -C</span>

<span class="token comment"># 通过环境变量控制布局</span>
<span class="token assign-left variable"><span class="token environment constant">COLUMNS</span></span><span class="token operator">=</span><span class="token number">80</span> <span class="token assign-left variable"><span class="token environment constant">LINES</span></span><span class="token operator">=</span><span class="token number">40</span> <span class="token function">htop</span>   <span class="token comment"># 指定终端尺寸布局</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用别名（写入 <code>~/.zshrc</code> 或 <code>~/.bashrc</code>）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">alias</span> <span class="token assign-left variable">htopmem</span><span class="token operator">=</span><span class="token string">&#39;htop -s PERCENT_MEM&#39;</span>   <span class="token comment"># 按内存排序</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">htopcpu</span><span class="token operator">=</span><span class="token string">&#39;htop -s PERCENT_CPU&#39;</span>   <span class="token comment"># 按 CPU 排序</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">htoproot</span><span class="token operator">=</span><span class="token string">&#39;sudo htop&#39;</span>            <span class="token comment"># root 视角查看所有进程</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-自定义配色与布局-f2-setup" tabindex="-1"><a class="header-anchor" href="#_3-自定义配色与布局-f2-setup" aria-hidden="true">#</a> 3. 自定义配色与布局（F2 Setup）</h3><p>在 htop 内按 <code>F2</code>（Setup）进入配置界面，可调整颜色方案（<code>Monochrome</code>、<code>Black on White</code> 等）、增减列、开关树形视图、配置 Meters 显示哪些指标。改动会自动写回 <code>htoprc</code>，实现&quot;一次配置、处处生效&quot;。</p><p>进阶技巧：把配置好的 <code>htoprc</code> 放进 dotfiles 仓库版本管理，换新机器或 SSH 到服务器时同步即可保持一致的监控界面。</p><h3 id="_4-多进程批量管理" tabindex="-1"><a class="header-anchor" href="#_4-多进程批量管理" aria-hidden="true">#</a> 4. 多进程批量管理</h3><p>按 <code>空格</code> 逐个标记（tag）多个进程后，按 <code>F9</code> 可一次性对标记的所有进程发送信号（如批量 <code>SIGTERM</code> 优雅关闭）。配合 <code>F8</code>/<code>F7</code> 还能批量调整优先级，适合清理僵尸或失控的批量任务。</p><p>标记后按 <code>F5</code> 切到树形视图，可快速看出哪些标记进程属于同一父进程，批量操作前先确认，避免误杀关键服务。</p><h3 id="_5-与其它工具搭配" tabindex="-1"><a class="header-anchor" href="#_5-与其它工具搭配" aria-hidden="true">#</a> 5. 与其它工具搭配</h3><ul><li>与 <code>ps</code>、<code>lsof</code>、<code>vm_stat</code> 结合做深度排查（如先用 <code>lsof</code> 找 PID，再用 <code>htop -p</code> 聚焦观察）；</li><li>与 <code>watch</code> 搭配做非交互快照：<code>watch -n 2 htop</code>（但更推荐直接 <code>htop -d 2</code>，交互能力更强）；</li><li>在 SSH 远程管理服务器时，htop 比 <code>top</code> 更直观，特别适合树形查看 nginx、php-fpm、Java 等父子进程关系；</li><li>与 <code>grep</code> 管道配合定位进程：<code>ps aux | grep -E &#39;node|java&#39;</code> 先缩小范围，再进 htop 精准观察。</li></ul><h3 id="_6-深入-进程树视图-f5-的实战读法" tabindex="-1"><a class="header-anchor" href="#_6-深入-进程树视图-f5-的实战读法" aria-hidden="true">#</a> 6. 深入：进程树视图（F5）的实战读法</h3><p>按 <code>F5</code>（或 <code>t</code>）切换树形视图后，进程按<strong>父子层级</strong>缩进展示。这是排查&quot;进程依赖/拉活/僵尸&quot;最有力的武器：</p><ul><li><strong>看启动归属</strong>：光标停在一个进程上，按 <code>l</code> 直接查看它打开的文件，按 <code>s</code> 查看它的系统调用（strace），按 <code>k</code> 精准发信号——树形视图能一眼看出&quot;谁是谁拉起的&quot;，避免误杀父进程导致整棵树崩溃。</li><li><strong>看状态列（S）</strong>：树形视图里留意每个进程的 STAT 列。<code>Z</code>（Zombie 僵尸，已死但未被父进程回收）是排查重点；<code>D</code>（不可中断睡眠）一般无法直接杀死；<code>T</code>（被停止）可用 <code>SIGCONT</code> 恢复。配合 <code>F4</code> 过滤 <code>Z</code>，可快速列出全部僵尸进程。</li><li><strong>折叠整棵子树</strong>：在树形视图下按 <code>+</code> / <code>-</code>（或方向键右/左）展开 / 折叠某个父进程的整棵子树，便于聚焦某一进程组而隐藏无关噪声。</li><li><strong>定位整个进程组</strong>：想对&quot;某个服务及其全部子进程&quot;统一处理时，先在树形视图里 <code>空格</code> 标记根进程，再按 <code>F9</code> 发 <code>SIGKILL</code>，注意此时要确认子树里没有关键服务。</li></ul><blockquote><p>注意：macOS 上树形视图对某些内核线程/launchd 层级展示与 Linux 略有差异，但父子关系逻辑一致。</p></blockquote><h3 id="_7-深入-筛选与排序的组合拳" tabindex="-1"><a class="header-anchor" href="#_7-深入-筛选与排序的组合拳" aria-hidden="true">#</a> 7. 深入：筛选与排序的组合拳</h3><p><code>F4</code>（过滤）和 <code>F6</code>（排序）是日常定位的两把刷子，掌握它们的组合能极大提升效率：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 运行中组合操作：</span>
<span class="token comment"># 1) F4 输入关键字（如 node）→ 只显示含 node 的进程</span>
<span class="token comment"># 2) F6 选 PERCENT_MEM → 在过滤结果内按内存排序</span>
<span class="token comment"># 3) 空格标记可疑项 → F9 批量处理</span>

<span class="token comment"># 通配符：F4 过滤支持简单通配（类似 shell glob），</span>
<span class="token comment"># 输入 *node* 可模糊匹配路径/命令中任意位置的 node</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用筛选场景速记：</p><table><thead><tr><th>目标</th><th>操作</th></tr></thead><tbody><tr><td>只看某用户进程</td><td>启动时 <code>htop -u 用户名</code>，或按 <code>u</code> 选择用户</td></tr><tr><td>只看某进程及其子进程</td><td><code>htop -F PID</code>（含全部后代）</td></tr><tr><td>只看内存排序前几</td><td><code>F6</code> 选 <code>PERCENT_MEM</code>，配合 <code>F4</code> 过滤业务名</td></tr><tr><td>只看僵尸进程</td><td><code>F4</code> 输入 <code>Z</code>（STAT 列），或用 <code>ps aux | awk &#39;$8~/Z/&#39;</code> 在外部定位</td></tr><tr><td>只看线程级占用</td><td>按 <code>H</code>（大写）切换&quot;线程 / 进程&quot;视图，默认只显示进程</td></tr></tbody></table><blockquote><p><code>H</code> 键在 htop 3.x 里切换线程显示；macOS 上线程视图能看清多线程程序的每个线程各自占多少 CPU，排查&quot;单线程卡死&quot;很有用。</p></blockquote><h3 id="_8-深入-发送信号的正确姿势-f9" tabindex="-1"><a class="header-anchor" href="#_8-深入-发送信号的正确姿势-f9" aria-hidden="true">#</a> 8. 深入：发送信号的正确姿势（F9）</h3><p><code>F9</code> 弹出的信号列表是对进程&quot;发信号&quot;的门户，不同信号的语义天差地别，务必分清：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>SIGTERM (15)   —— 优雅终止，进程可捕获并做清理后退出。首选。
SIGKILL (9)    —— 强制杀死，不可捕获，可能丢数据/损坏文件。最后手段。
SIGSTOP (19)   —— 暂停进程（挂起），不终止，可用 SIGCONT 恢复。
SIGCONT (18)   —— 恢复被暂停的进程。
SIGHUP (1)     —— 挂断，常用于让守护进程重新加载配置（配合 -HUP 软重载）。
SIGINT (2)     —— 中断，等价于 Ctrl+C。
SIGUSR1/2      —— 程序自定义信号，常用于日志轮转/热重载（如 nginx reload）。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>想让 nginx 热重载配置而不是杀掉它：找到 <code>nginx: master</code> 进程，<code>F9</code> 选 <code>SIGHUP</code>，比 <code>kill -HUP</code> 更直观。</li><li>让某个卡住的进程&quot;暂停&quot;观察而非杀死：<code>F9</code> 选 <code>SIGSTOP</code>，看完再用 <code>F9</code> 选 <code>SIGCONT</code> 恢复。</li><li>用 <code>F7</code>/<code>F8</code>（renice）调整进程优先级：<code>nice</code> 值越小优先级越高。普通用户只能把自己的进程往 <code>0</code> 方向调（提高 nice 即降低优先级），调低（提高优先级）需要 root。</li></ul><h3 id="_9-深入-完整监控面板解读" tabindex="-1"><a class="header-anchor" href="#_9-深入-完整监控面板解读" aria-hidden="true">#</a> 9. 深入：完整监控面板解读</h3><p>htop 的界面分为三块，读懂它们等于看懂整台机器的&quot;体检报告&quot;：</p><p><strong>① 顶部 Meters（左侧/右侧仪表区）</strong></p><ul><li><code>AllCPUs</code>：每个 CPU 核心的独立进度条，颜色表示状态：绿色=用户态、红色=系统态（内核）、蓝色=低优先级、黄色/洋红=某些特殊状态。若满屏发红，说明系统调用/内核繁忙。</li><li><code>Memory</code>：内存使用条。百分比 =（total - available）/ total，<code>available</code> 包含可回收的缓存，所以&quot;已用&quot;未必是真实压力。</li><li><code>Swap</code>：交换分区使用。swap 长期高说明物理内存吃紧。</li><li><code>LoadAverage</code>：负载均值，<code>1.23/0.98/0.76</code> 分别是 1/5/15 分钟平均。单核机器 load &gt; 1 即过载；多核则按核数判断。</li><li><code>Tasks</code> / <code>Threads</code> / <code>Uptime</code>：进程数、线程数、开机时长。</li></ul><p><strong>② 中部表头</strong></p><p>各列含义：<code>PID</code>（进程号）、<code>USER</code>（属主）、<code>PRI</code>/<code>NI</code>（优先级）、<code>VIRT</code>（虚拟内存）、<code>RES</code>（常驻物理内存）、<code>SHR</code>（共享内存）、<code>S</code>（状态）、<code>CPU%</code>、<code>MEM%</code>、<code>TIME+</code>（累计 CPU 时间）、<code>Command</code>（命令）。</p><p><strong>③ 底部功能区</strong></p><p>列出 F1~F10 各功能键的即时提示，按对应键即可触发，是新手最好的&quot;菜单栏&quot;。</p><h3 id="_10-深入-让-htop-自动匹配每台机器的配置" tabindex="-1"><a class="header-anchor" href="#_10-深入-让-htop-自动匹配每台机器的配置" aria-hidden="true">#</a> 10. 深入：让 htop 自动匹配每台机器的配置</h3><p>把配置做成&quot;按主机/环境区分&quot;的模板，配合脚本在 SSH 登录或 <code>tmux</code> 会话里自动加载：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ~/.zshrc 里的辅助函数：按 SSH 目标主机加载不同 htoprc</span>
<span class="token function-name function">htopssh</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token builtin class-name">local</span> <span class="token assign-left variable">host</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$1</span>&quot;</span>
  <span class="token comment"># 若该主机有专属配置则用之，否则用默认</span>
  <span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-f</span> <span class="token string">&quot;<span class="token environment constant">$HOME</span>/.config/htop/htoprc.<span class="token variable">$host</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span>
    <span class="token assign-left variable">HTOP_HOME</span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>/.config/htop&quot;</span> <span class="token assign-left variable"><span class="token environment constant">HOME</span></span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>&quot;</span> <span class="token function">htop</span> <span class="token punctuation">\\</span>
      <span class="token parameter variable">--config</span> <span class="token string">&quot;<span class="token environment constant">$HOME</span>/.config/htop/htoprc.<span class="token variable">$host</span>&quot;</span>
  <span class="token keyword">else</span>
    <span class="token function">htop</span>
  <span class="token keyword">fi</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="新手易踩的坑" tabindex="-1"><a class="header-anchor" href="#新手易踩的坑" aria-hidden="true">#</a> 新手易踩的坑</h3><ol><li><p><strong>必须使用原生终端颜色</strong>：htop 依赖终端 ANSI 颜色，某些浅色主题下文字可能看不清。可用 <code>htop -C</code>（Monochrome 纯色）运行，或在 <code>F2 -&gt; Colors</code> 里切换为深色配色。</p></li><li><p><strong><code>htop -p</code> 跟的是 PID 不是端口</strong>：这是最常见的误解。想查端口占用必须先 <code>lsof -nP -iTCP:8080</code> 拿到 PID，再 <code>htop -p &lt;PID&gt;</code>，直接用端口号会报错或无输出。</p></li><li><p><strong>权限导致无法操作某些进程</strong>：普通用户执行 <code>F9</code> 杀死 root 或其他用户的进程、<code>F7</code>/<code>F8</code> 调整其优先级会被拒绝。需要用 <code>sudo htop</code> 以 root 运行才能操作全部进程（<code>sudo</code> 后 htop 会显示所有用户进程）。</p></li><li><p><strong><code>brew uninstall htop</code> 后残留配置</strong>：Homebrew 默认不会删除 <code>~/.config/htop/htoprc</code>，重装后旧配置仍在。如需彻底清除，手动删除 <code>~/.config/htop</code> 目录即可。</p></li><li><p><strong>刷新间隔与负载</strong>：默认每秒刷新一次。在配置很弱的机器或大量进程时，可调大刷新间隔（<code>htop -d 5</code>）以降低自身 CPU 占用；htop 本身是轻量程序，但海量进程下频繁刷新仍会有一点开销。</p></li><li><p><strong>在 CI/脚本中使用</strong>：htop 是交互式工具，不适合在无人值守脚本中直接调用；自动化场景请改用 <code>ps</code> 或 <code>top -bn1</code> 等非交互输出（详见第七节）。</p></li></ol><h3 id="常见报错与解决办法" tabindex="-1"><a class="header-anchor" href="#常见报错与解决办法" aria-hidden="true">#</a> 常见报错与解决办法</h3><table><thead><tr><th>报错 / 现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>htop: command not found</code></td><td>未安装或 PATH 未包含</td><td><code>brew install htop</code>；<code>brew update</code> 后重试</td></tr><tr><td>提示缺少 locale 或乱码</td><td>终端 locale 未设置</td><td><code>export LANG=en_US.UTF-8</code> 后重开终端</td></tr><tr><td>CPU 温度/频率列不显示数据</td><td>传感器不被支持（macOS 常见）</td><td>在 <code>F2 -&gt; Display options</code> 关闭该 Meter</td></tr><tr><td>颜色错乱、花屏</td><td>终端不支持 ANSI 或宽字符</td><td><code>htop -C</code> 强制纯色，或换用 iTerm2/kitty</td></tr><tr><td><code>F9</code> 杀不掉进程</td><td>无权限或进程处于不可中断状态（D 状态）</td><td><code>sudo htop</code>；D 状态进程一般只能重启系统</td></tr><tr><td>htop 打开立即退出</td><td>终端尺寸过小</td><td><code>export COLUMNS=80 LINES=40</code> 或拉大窗口</td></tr><tr><td>某个进程 CPU% 超过 100%</td><td>多核/多线程进程，CPU% 是相对单核百分比</td><td>属正常，说明该进程用满了一个以上核心</td></tr><tr><td>树形视图缩进错乱</td><td>父进程已退出或终端字体非等宽</td><td>确认用等宽字体；<code>F5</code> 重绘一次</td></tr><tr><td>运行中 <code>q</code> 退出后终端残留花屏</td><td>终端/环境异常</td><td>执行 <code>reset</code> 或 <code>stty sane</code> 恢复终端</td></tr></tbody></table><h3 id="性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#性能与安全注意点" aria-hidden="true">#</a> 性能与安全注意点</h3><ol><li><strong>性能</strong>：在拥有数千进程的服务器上，默认 1 秒刷新会带来可见开销，建议 <code>htop -d 5</code> 或更高；排查高峰期别同时开多个 htop 实例。</li><li><strong>安全</strong>：<code>sudo htop</code> 赋予的是整个终端的 root 权限，用完立即退出；不要长期挂 root 会话。</li><li><strong>SIGKILL 要慎重</strong>：<code>F9</code> 默认列表在 <code>SIGKILL</code> 上（有些版本是 <code>SIGTERM</code>）。SIGKILL（9）不可被进程捕获，会直接强制终止、可能丢失未保存数据；优先尝试 <code>SIGTERM</code>（15）优雅退出，无效再升级到 SIGKILL。</li><li><strong>不要乱 <code>-HUP</code></strong>：给不支持 HUP 语义的进程发 <code>SIGHUP</code> 可能直接终止它，而非重载。确认目标进程文档里说明支持 HUP 再发。</li><li><strong>共享服务器上别开 <code>htop -u root</code> 挂机</strong>：会暴露所有用户进程列表，涉及隐私；只在排障必要时临时使用并退出。</li></ol><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><p>htop 本身是交互式工具，但可以把它与命令行工具、脚本、CI 组装成一套完整的<strong>进程排查与监控工作流</strong>。</p><h3 id="_1-命令行排查链路-端口-→-进程-→-资源" tabindex="-1"><a class="header-anchor" href="#_1-命令行排查链路-端口-→-进程-→-资源" aria-hidden="true">#</a> 1. 命令行排查链路（端口 → 进程 → 资源）</h3><p>一条龙定位&quot;谁占着端口 8080，吃了多少内存&quot;：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 第 1 步：找 PID</span>
<span class="token function">lsof</span> <span class="token parameter variable">-nP</span> <span class="token parameter variable">-iTCP:8080</span> <span class="token parameter variable">-sTCP:LISTEN</span>
<span class="token comment"># 输出：COMMAND  PID  ...  node   12345  ...  :::8080 (LISTEN)</span>

<span class="token comment"># 第 2 步：确认进程身份（可选）</span>
<span class="token function">ps</span> <span class="token parameter variable">-p</span> <span class="token number">12345</span> <span class="token parameter variable">-o</span> pid,ppid,user,cmd

<span class="token comment"># 第 3 步：htop 聚焦观察该进程的实时 CPU/内存</span>
<span class="token function">htop</span> <span class="token parameter variable">-p</span> <span class="token number">12345</span>

<span class="token comment"># 第 4 步：查看进程打开的文件/内存映射，判断是否异常</span>
<span class="token function">lsof</span> <span class="token parameter variable">-p</span> <span class="token number">12345</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-20</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-脚本化-用非交互命令取数-喂给告警或日志" tabindex="-1"><a class="header-anchor" href="#_2-脚本化-用非交互命令取数-喂给告警或日志" aria-hidden="true">#</a> 2. 脚本化：用非交互命令取数，喂给告警或日志</h3><p>htop 无批处理模式，需要数据时用 <code>ps</code> 或 <code>top -bn1</code> 取非交互输出，再交给脚本处理：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># monitor_cpu.sh —— 找出 CPU 占用最高的前 5 个进程</span>
<span class="token function">ps</span> <span class="token parameter variable">-A</span> <span class="token parameter variable">-o</span> pcpu,pmem,pid,comm <span class="token parameter variable">--sort</span><span class="token operator">=</span>-pcpu <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-6</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>top -bn1</code> 拍快照，适合记录到日志：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 单次快照输出到文件（-b 批处理 -n1 只拍一帧）</span>
<span class="token function">top</span> <span class="token parameter variable">-bn1</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-20</span> <span class="token operator">&gt;</span> /tmp/top_snapshot_<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d%H%M%S<span class="token variable">)</span></span>.log
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-makefile-自动化" tabindex="-1"><a class="header-anchor" href="#_3-makefile-自动化" aria-hidden="true">#</a> 3. Makefile 自动化</h3><p>把常用的监控任务固化到 Makefile，一键执行：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile</span>
<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> mon top-log find-port zombie

<span class="token comment"># 交互式查看资源占用 Top</span>
<span class="token target symbol">mon</span><span class="token punctuation">:</span>
	htop -d 1

<span class="token comment"># 生成一份 top 快照日志</span>
<span class="token target symbol">top-log</span><span class="token punctuation">:</span>
	mkdir -p logs
	top -bn1 <span class="token operator">|</span> head -25 &gt; logs/top_<span class="token variable">$$</span><span class="token punctuation">(</span>date +%Y%m%d_%H%M%S<span class="token punctuation">)</span>.log
	<span class="token operator">@</span>echo <span class="token string">&quot;已写入 logs/&quot;</span>

<span class="token comment"># 查端口占用</span>
<span class="token target symbol">find-port</span><span class="token punctuation">:</span>
	<span class="token operator">@</span>read -p <span class="token string">&quot;输入端口: &quot;</span><span class="token target symbol"> p; lsof -nP -iTCP</span><span class="token punctuation">:</span><span class="token variable">$$p</span> -sTCP<span class="token punctuation">:</span>LISTEN

<span class="token comment"># 列出全部僵尸进程（Z 状态）</span>
<span class="token target symbol">zombie</span><span class="token punctuation">:</span>
	ps aux <span class="token operator">|</span> awk <span class="token string">&#39;$$8 ~ /Z/ {print}&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">make</span> mon        <span class="token comment"># 进入 htop 交互界面</span>
<span class="token function">make</span> top-log    <span class="token comment"># 落一份 top 快照</span>
<span class="token function">make</span> find-port  <span class="token comment"># 交互输入端口查占用</span>
<span class="token function">make</span> zombie     <span class="token comment"># 列出僵尸进程</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-ci-集成-进程泄漏-内存压力检查" tabindex="-1"><a class="header-anchor" href="#_4-ci-集成-进程泄漏-内存压力检查" aria-hidden="true">#</a> 4. CI 集成：进程泄漏/内存压力检查</h3><p>在 CI 中（如 GitHub Actions、GitLab CI）不能开交互式 htop，但可用 <code>ps</code>/<code>top</code> 做资源断言，防止提交导致内存泄漏或进程暴增：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/check.yml（片段）</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 检查进程数量
  <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
    # 记录测试前后进程数，超过阈值即失败
    before=$(ps -e | wc -l | tr -d &#39; &#39;)
    echo &quot;before=$before&quot;
    # ... 运行你的测试或应用 ...
    after=$(ps -e | wc -l | tr -d &#39; &#39;)
    echo &quot;after=$after&quot;
    [ $((after - before)) -lt 50 ] &amp;&amp; echo &quot;进程数正常&quot; || { echo &quot;进程泄漏!&quot;; exit 1; }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-批量处理-一次性清理一批僵尸-失控进程" tabindex="-1"><a class="header-anchor" href="#_5-批量处理-一次性清理一批僵尸-失控进程" aria-hidden="true">#</a> 5. 批量处理：一次性清理一批僵尸/失控进程</h3><p>先用 <code>ps</code> 过滤出目标，再批量发信号（避免误杀，先 <code>echo</code> 演练再真删）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 找出所有 python 异常进程并优雅终止（演练版：先只看不杀）</span>
<span class="token function">ps</span> aux <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;$3 &gt; 90 &amp;&amp; /python/ {print $2}&#39;</span>

<span class="token comment"># 确认后批量 SIGTERM</span>
<span class="token function">ps</span> aux <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;$3 &gt; 90 &amp;&amp; /python/ {print $2}&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">kill</span> <span class="token parameter variable">-15</span>

<span class="token comment"># 若仍不退出，再升级 SIGKILL</span>
<span class="token function">ps</span> aux <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;$3 &gt; 90 &amp;&amp; /python/ {print $2}&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">kill</span> <span class="token parameter variable">-9</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-信号发送与-kill-命令的脚本化等价" tabindex="-1"><a class="header-anchor" href="#_6-信号发送与-kill-命令的脚本化等价" aria-hidden="true">#</a> 6. 信号发送与 <code>kill</code> 命令的脚本化等价</h3><p>htop 里用 <code>F9</code> 发信号，脚本里对应 <code>kill</code> 命令。两者的信号语义完全一致，只是交互与批处理之别：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 让 nginx 主进程热重载（等价于 htop 里选中 master 按 F9 选 SIGHUP）</span>
<span class="token function">kill</span> <span class="token parameter variable">-HUP</span> <span class="token variable"><span class="token variable">$(</span>pgrep <span class="token parameter variable">-f</span> <span class="token string">&#39;nginx: master&#39;</span><span class="token variable">)</span></span>

<span class="token comment"># 优雅停止全部 node 服务</span>
<span class="token function">pkill</span> <span class="token parameter variable">-TERM</span> <span class="token function">node</span>

<span class="token comment"># 暂停/恢复某 PID（等价于 F9 选 SIGSTOP/SIGCONT）</span>
<span class="token function">kill</span> <span class="token parameter variable">-STOP</span> <span class="token number">12345</span> <span class="token operator">&amp;&amp;</span> <span class="token function">sleep</span> <span class="token number">5</span> <span class="token operator">&amp;&amp;</span> <span class="token function">kill</span> <span class="token parameter variable">-CONT</span> <span class="token number">12345</span>

<span class="token comment"># 列出某 PID 能收到的全部信号（调试用）</span>
<span class="token function">kill</span> <span class="token parameter variable">-l</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-与-tmux-screen-搭配做-常驻监控窗格" tabindex="-1"><a class="header-anchor" href="#_7-与-tmux-screen-搭配做-常驻监控窗格" aria-hidden="true">#</a> 7. 与 <code>tmux</code> / <code>screen</code> 搭配做&quot;常驻监控窗格&quot;</h3><p>在服务器上常开一个 htop 监控窗格，不占主屏、随时切回查看：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 在 tmux 会话里开一个专用监控窗格</span>
tmux new <span class="token parameter variable">-d</span> <span class="token parameter variable">-s</span> mon <span class="token string">&#39;htop -d 2&#39;</span>
<span class="token comment"># 之后随时切回：tmux attach -t mon</span>
<span class="token comment"># 或在一个窗格里分屏：先 Ctrl+B &quot;，再在新窗格跑 htop</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-生产级实践清单" tabindex="-1"><a class="header-anchor" href="#_8-生产级实践清单" aria-hidden="true">#</a> 8. 生产级实践清单</h3><ul><li><strong>固定监控配置</strong>：把精心调好的 <code>~/.config/htop/htoprc</code> 纳入 dotfiles 或配置管理工具（Ansible/Chef），全服务器统一界面。</li><li><strong>非交互取数</strong>：所有需要定时采集、告警、落库的场景一律用 <code>ps</code>/<code>top -bn1</code>/<code>vm_stat</code>，绝不在 cron 里跑 htop。</li><li><strong>权限最小化</strong>：运维机器人/CI 用非 root 账号跑监控脚本；需要杀进程时才临时 <code>sudo</code>。</li><li><strong>多维度结合</strong>：<code>htop</code>（实时交互）＋ <code>lsof</code>（端口/文件）＋ <code>vm_stat</code>/<code>top -bn1</code>（历史快照）三件套，覆盖&quot;现在看什么、刚才怎样、谁占资源&quot;三个问题。</li><li><strong>树形视图排查依赖</strong>：服务异常时按 <code>F5</code> 看父子关系，能快速判断是主进程挂了还是子进程被反复拉起，配合 <code>F9</code> 针对性地处理整个进程组。</li><li><strong>先 SIGTERM 后 SIGKILL</strong>：任何&quot;杀进程&quot;操作都遵守&quot;先优雅、再强制&quot;的顺序，并养成&quot;先标记、后确认、再执行&quot;的习惯，避免生产事故。</li></ul>`,102),d=[o];function c(i,l){return a(),s("div",null,d)}const u=n(t,[["render",c],["__file","htop.html.vue"]]);export{u as default};
